package prim

import (
	"sync"

	"github.com/energye/gpui/render"
	"github.com/energye/gpui/ui/rendering"
	"github.com/energye/gpui/ui/theme"
)

// CustomSVGPath is one SVG subpath with optional fixed fill.
// Fill "" or "currentColor" means use the icon main color;
// otherwise Fill is a #rgb/#rrggbb fixed color (e.g. panda face).
type CustomSVGPath struct {
	D    string
	Fill string
}

// CustomSVGEntry is one offline custom symbol (custom.tsx heart/panda,
// iconfont.cn symbols). ViewBox follows SVG (minX minY w h).
type CustomSVGEntry struct {
	Key        string
	MinX, MinY float64
	W, H       float64
	Paths      []CustomSVGPath
}

var (
	customMu     sync.RWMutex
	customIndex  = map[string]*CustomSVGEntry{}
	customParsed = map[string][]antdParsedPath{}
)

// RegisterCustomSVG adds one offline symbol; later keys win.
func RegisterCustomSVG(e CustomSVGEntry) {
	if e.Key == "" || e.W <= 0 || e.H <= 0 || len(e.Paths) == 0 {
		return
	}
	customMu.Lock()
	defer customMu.Unlock()
	cp := e
	cp.Paths = append([]CustomSVGPath(nil), e.Paths...)
	customIndex[e.Key] = &cp
	delete(customParsed, e.Key)
}

// IsKnownCustomSVG reports offline custom coverage.
func IsKnownCustomSVG(key string) bool {
	customMu.RLock()
	_, ok := customIndex[key]
	customMu.RUnlock()
	return ok
}

func lookupCustomSVG(key string) *CustomSVGEntry {
	customMu.RLock()
	e := customIndex[key]
	customMu.RUnlock()
	return e
}

func parsedCustomPaths(key string) []antdParsedPath {
	customMu.RLock()
	if list, ok := customParsed[key]; ok {
		customMu.RUnlock()
		return list
	}
	customMu.RUnlock()
	e := lookupCustomSVG(key)
	if e == nil {
		return nil
	}
	var list []antdParsedPath
	for _, p := range e.Paths {
		parsed, err := render.ParseSVGPath(p.D)
		if err != nil || parsed == nil {
			continue
		}
		list = append(list, antdParsedPath{path: parsed, fill: p.Fill})
	}
	customMu.Lock()
	customParsed[key] = list
	customMu.Unlock()
	return list
}

// PaintCustomSVG fills one offline symbol in a size x size box.
// Returns false when unknown. Fixed fills use their hex;
// ""/currentColor paths use main. Uniform scale preserves aspect;
// content centers when W != H (e.g. 1029x1024 python).
func PaintCustomSVG(pc *rendering.PaintContext, size float64, key string, main theme.Color) bool {
	if pc == nil || size <= 0 {
		return false
	}
	e := lookupCustomSVG(key)
	if e == nil {
		return false
	}
	list := parsedCustomPaths(key)
	if len(list) == 0 {
		return false
	}
	maxWH := e.W
	if e.H > maxWH {
		maxWH = e.H
	}
	scale := size / maxWH
	offX := (size - e.W*scale) / 2
	offY := (size - e.H*scale) / 2
	base := render.Translate(offX, offY).Multiply(render.Scale(scale, scale)).Multiply(render.Translate(-e.MinX, -e.MinY))
	for _, pp := range list {
		var r, g, b, a float64
		if pp.fill == "" || pp.fill == "currentColor" {
			r, g, b, a = main.R, main.G, main.B, main.A
		} else {
			c := theme.Hex(pp.fill)
			r, g, b, a = c.R, c.G, c.B, c.A
		}
		if a <= 0 {
			continue
		}
		tp := pp.path.Transform(base)
		rendering.FillPath(pc, tp, r, g, b, a)
	}
	return true
}

// CustomSVGPainterFor builds a Painter with rotation about center.
func CustomSVGPainterFor(size float64, key string, main theme.Color, angleDeg float64) Painter {
	return func(pc *rendering.PaintContext, box rendering.Size) {
		if pc == nil {
			return
		}
		if angleDeg != 0 {
			cx, cy := box.Width/2, box.Height/2
			pc.Save()
			pc.RotateAbout(angleDeg*3.141592653589793/180, cx, cy)
			PaintCustomSVG(pc, size, key, main)
			pc.RestoreCanvas()
			return
		}
		PaintCustomSVG(pc, size, key, main)
	}
}

